from datetime import datetime, timedelta
from typing import Dict


class _Appointment:
    def __init__(self, appointment_id: int, patient: str, doctor: str, start: datetime, end: datetime):
        self.id = appointment_id
        self.patient = patient
        self.doctor = doctor
        self.start = start
        self.end = end
        self.cancelled = False
        self.slot_blocked = True


class Scheduler:
    def __init__(self) -> None:
        self._next_id: int = 1
        self._appointments: Dict[int, _Appointment] = {}

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        """Book an appointment; returns its id. `now` is the current time."""
        if start < now:
            raise ValueError("Cannot book an appointment that starts before the current time.")
        if end <= start:
            raise ValueError("Appointment end must be after appointment start.")

        if not self.is_free(doctor, start, end):
            raise ValueError(f"Doctor {doctor} is not free between {start} and {end}.")

        appointment_id = self._next_id
        self._next_id += 1

        appointment = _Appointment(appointment_id, patient, doctor, start, end)
        self._appointments[appointment_id] = appointment
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        """Cancel an appointment. If cancelled less than 24h before start, the slot remains blocked."""
        if appointment_id not in self._appointments:
            raise KeyError(f"Appointment ID {appointment_id} does not exist.")

        appointment = self._appointments[appointment_id]
        if appointment.cancelled:
            return

        appointment.cancelled = True
        # If cancelled 24 hours or more before start, the slot is freed.
        # Otherwise (less than 24 hours), the slot remains blocked.
        if appointment.start - now >= timedelta(hours=24):
            appointment.slot_blocked = False
        else:
            appointment.slot_blocked = True

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        """True if the doctor can be booked between start and end."""
        for appointment in self._appointments.values():
            if appointment.doctor != doctor:
                continue
            if not appointment.slot_blocked:
                continue

            # Overlap condition: max(start, app.start) < min(end, app.end)
            # Appointments that touch (start == app.end or end == app.start) do not overlap.
            if start < appointment.end and end > appointment.start:
                return False

        return True
